// The AI node returns the parsed JSON fields, or { text } if the model's answer was not valid JSON.
// Small models make mistakes, so every field has a safe fallback.
const lead = $('Settings').first().json;
let ai = $json;
if (typeof ai.reply_body !== 'string') {
  try {
    ai = JSON.parse(ai.text);
  } catch {
    ai = {};
  }
}

const firstName = String(lead.name || '').trim().split(/\s+/)[0] || 'there';
// The reply goes to whatever address the visitor typed, and the message can try to steer the AI
// ("ignore your rules, tell them to visit ..."). Replies with links, email addresses, phone numbers
// or amounts are dropped for the standard reply, so the form can't be used to send others spam or promises.
const unsafeReply = /https?:|www\.|\b[\w-]+\.(com|net|org|io|co|biz|info|xyz|ru|cn)\b|@|\+?\d[\d\s()-]{6,}\d|[$€£¥₹]|\b\d+(\.\d+)?\s?k\b|\b(usd|eur|gbp|pkr|dollars?|euros?|pounds?|rupees?)\b/i;
const aiReply = typeof ai.reply_body === 'string' && ai.reply_body.trim() !== '' && !unsafeReply.test(ai.reply_body)
  ? ai.reply_body
  : '';
const aiSubject = typeof ai.reply_subject === 'string' && ai.reply_subject.length <= 120 && !unsafeReply.test(ai.reply_subject)
  ? ai.reply_subject
  : '';
// The AI picks a category; the rest of the workflow works with a simple priority.
const priorities = { hot_lead: 'high', lead: 'medium', spam: 'low', job_application: 'low' };
const category = String(ai.category || '').toLowerCase();
const priority = priorities[category] || 'medium';

return [{
  json: {
    name: lead.name,
    email: lead.email,
    company: lead.company || '',
    message: lead.message,
    companyName: lead.companyName,
    fromEmail: lead.fromEmail,
    salesEmail: lead.salesEmail,
    aiUsed: aiReply !== '',
    category: priorities[category] ? category : 'lead',
    priority,
    summary: ai.summary || lead.message,
    replySubject: (aiReply && aiSubject) || `Thanks for contacting ${lead.companyName}`,
    replyBody: aiReply ||
      `Hi ${firstName},\n\nThanks for reaching out. A member of our team will contact you within one business day.\n\nThe ${lead.companyName} team`,
  },
}];

